/*
 * A055189  Cumulative counting sequence: method A
 *          (adjective-before-noun)-pairs, starting with 3.
 * https://oeis.org/A055189
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by successive segments. Each segment consists
 *            of pairs (count_of_x, x) for every distinct integer x that has
 *            appeared so far, listed in the order of first appearance. The
 *            sequence starts with the segment [3]
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>

seq_t a(idx_t n) {
    /* static storage for the entire sequence and its state */
    static seq_t *seq = NULL;
    static size_t seq_len = 0, seq_cap = 0;
    static seq_t *distinct = NULL;
    static idx_t *counts = NULL;
    static size_t *order = NULL;
    static size_t distinct_len = 0, distinct_cap = 0;
    static size_t order_len = 0, order_cap = 0;

    /* initialization: first segment [3] */
    if (seq == NULL) {
        seq_cap = 16;
        seq = (seq_t *)malloc(seq_cap * sizeof(seq_t));
        seq_len = 0;

        distinct_cap = 8;
        distinct = (seq_t *)malloc(distinct_cap * sizeof(seq_t));
        counts = (idx_t *)malloc(distinct_cap * sizeof(idx_t));
        distinct_len = 0;

        order_cap = 8;
        order = (size_t *)malloc(order_cap * sizeof(size_t));
        order_len = 0;

        /* add the initial number 3 */
        seq[seq_len++] = (seq_t)3;

        distinct[distinct_len] = (seq_t)3;
        counts[distinct_len] = 1;
        if (order_len == order_cap) {
            order_cap *= 2;
            order = (size_t *)realloc(order, order_cap * sizeof(size_t));
        }
        order[order_len++] = distinct_len;
        distinct_len++;
    }

    /* generate segments until we have at least n terms */
    while (seq_len < n) {
        size_t ord_size = order_len;
        /* cache current counts of all numbers in order */
        idx_t *tmp_counts = (idx_t *)malloc(ord_size * sizeof(idx_t));
        for (size_t i = 0; i < ord_size; ++i) {
            tmp_counts[i] = counts[order[i]];
        }

        for (size_t i = 0; i < ord_size; ++i) {
            seq_t val = distinct[order[i]];
            idx_t cnt = tmp_counts[i];

            /* append count */
            if (seq_len == seq_cap) {
                seq_cap *= 2;
                seq = (seq_t *)realloc(seq, seq_cap * sizeof(seq_t));
            }
            seq[seq_len++] = (seq_t)cnt;

            /* update count for the number 'cnt' */
            size_t pos = 0;
            while (pos < distinct_len && distinct[pos] != (seq_t)cnt) pos++;
            if (pos == distinct_len) { /* new distinct number */
                if (distinct_len == distinct_cap) {
                    distinct_cap *= 2;
                    distinct = (seq_t *)realloc(distinct, distinct_cap * sizeof(seq_t));
                    counts = (idx_t *)realloc(counts, distinct_cap * sizeof(idx_t));
                }
                distinct[distinct_len] = (seq_t)cnt;
                counts[distinct_len] = 1;
                pos = distinct_len;
                distinct_len++;
                if (order_len == order_cap) {
                    order_cap *= 2;
                    order = (size_t *)realloc(order, order_cap * sizeof(size_t));
                }
                order[order_len++] = pos;
            } else {
                counts[pos]++;
            }

            /* append value */
            if (seq_len == seq_cap) {
                seq_cap *= 2;
                seq = (seq_t *)realloc(seq, seq_cap * sizeof(seq_t));
            }
            seq[seq_len++] = val;

            /* update count for the number 'val' */
            pos = 0;
            while (pos < distinct_len && distinct[pos] != val) pos++;
            if (pos == distinct_len) { /* new distinct number */
                if (distinct_len == distinct_cap) {
                    distinct_cap *= 2;
                    distinct = (seq_t *)realloc(distinct, distinct_cap * sizeof(seq_t));
                    counts = (idx_t *)realloc(counts, distinct_cap * sizeof(idx_t));
                }
                distinct[distinct_len] = val;
                counts[distinct_len] = 1;
                pos = distinct_len;
                distinct_len++;
                if (order_len == order_cap) {
                    order_cap *= 2;
                    order = (size_t *)realloc(order, order_cap * sizeof(size_t));
                }
                order[order_len++] = pos;
            } else {
                counts[pos]++;
            }
        }
        free(tmp_counts);
    }
    return seq[(size_t)(n - 1)];
}
